import React, { useContext, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  Link, matchRoutes, renderMatches, useLocation, useNavigationType,
  UNSAFE_LocationContext as LocationContext,
  UNSAFE_NavigationContext as NavigationContext,
} from "react-router-dom";
import LandingHeader from "../../Header/LandingHeader";
import LandingFooter from "../../Footer/LandingFooter";
import AdvisoryBoard from "../Static/AdvisoryBoard";
import BlogPage from "../Static/BlogPage";
import BorrowerPage from "../Static/BorrowerPage";
import ContactUs from "../Static/ContactUs";
import FAQPage from "../Static/FAQPage";
import GrievanceRedressal from "../Static/GrievanceRedressal";
import HowItWorks from "../Static/HowItWorks";
import InternationalBusinessExpansion from "../Static/InternationalBusinessExpansion";
import KnowYourEarnings from "../Static/KnowYourEarnings";
import KnowYourFees from "../Static/KnowYourFees";
import KnowYourTax from "../Static/KnowYourTax";
import LatestEGMNotice from "../Static/LatestEGMNotice";
import LenderPage from "../Static/LenderPage";
import LoanEmiCalculator from "../Static/LoanEmiCalculator";
import LoanPerformance from "../Static/LoanPerformance";
import MotorLoan from "../Static/MotorLoan";
import PersonalLoan from "../Static/PersonalLoan";
import PrivacyPolicy from "../Static/PrivacyPolicy";
import RBIDirections from "../Static/RBIDirections";
import SMELoan from "../Static/SMELoan";
import TeamManagement from "../Static/TeamManagement";
import TermsOfService from "../Static/TermsOfService";
import TransparencyDisclosures from "../Static/TransparencyDisclosures";
import TravelLoan from "../Static/TravelLoan";
import { previewHome, publicPreviewHref, publicPreviewPages } from "./publicPreviewPaths";
import "./PreviewPublicView.css";

function PreviewBlog() {
  const { search } = useLocation();
  const navigationType = useNavigationType();
  const previousSearch = useRef(search);
  const [revision, setRevision] = useState(0);

  // The original blog reads filters on mount. Restore them on Back/Forward
  // while keeping the search field and its caret in place during typing.
  useLayoutEffect(() => {
    const changed = previousSearch.current !== search;
    previousSearch.current = search;
    if (changed && navigationType === "POP") setRevision(value => value + 1);
  }, [search, navigationType]);

  return <BlogPage key={revision} />;
}

function TermsPreview() {
  return (
    <>
      <LandingHeader standalone showProgressBar={false} showSocialDock={false} />
      <main className="oxy-public-terms"><TermsOfService /></main>
      <LandingFooter />
    </>
  );
}

const screens = {
  AdvisoryBoard, BlogPage: PreviewBlog, BorrowerPage, ContactUs,
  FAQPage, GrievanceRedressal, HowItWorks, InternationalBusinessExpansion,
  KnowYourEarnings, KnowYourFees, KnowYourTax, LatestEGMNotice,
  LenderPage, LoanEmiCalculator, LoanPerformance, MotorLoan,
  PersonalLoan, PrivacyPolicy, RBIDirections, SMELoan,
  TeamManagement, TermsPreview, TransparencyDisclosures, TravelLoan,
};

const pages = publicPreviewPages.map(({ path, screen, art }) => {
  const Page = screens[screen];
  return { path, art, element: Page === FAQPage ? <FAQPage defaultCategory="all" /> : <Page /> };
});

export default function PreviewPublicView({ location }) {
  const outer = useContext(NavigationContext);
  const navigationType = useNavigationType();
  const page = useRef(null);

  useEffect(() => {
    const heading = page.current?.querySelector("h1")?.textContent.trim();
    if (!heading) return;
    const previousTitle = document.title;
    const title = heading + " | OxyLoans";
    document.title = title;
    return () => { if (document.title === title) document.title = previousTitle; };
  }, [location.pathname]);

  // Scope React Router v6's location and link writer to the existing public page.
  // Its own Links, useSearchParams, and useNavigate continue to share browser history.
  const navigation = useMemo(() => {
    const history = outer.navigator;
    return { ...outer, navigator: {
      createHref: to => history.createHref(publicPreviewHref(to)),
      push: (to, state, options) => history.push(publicPreviewHref(to), state, options),
      replace: (to, state, options) => history.replace(publicPreviewHref(to), state, options),
      go: delta => history.go(delta),
    } };
  }, [outer]);
  const matches = matchRoutes(pages, location);
  if (!matches) {
    return (
      <main className="oxy-public-preview oxy-public-missing">
        <h1>Page unavailable</h1>
        <Link to={previewHome}>Return to OxyLoans</Link>
      </main>
    );
  }
  const { route } = matches[matches.length - 1];
  return (
    <div ref={page} className="oxy-public-preview" data-art={route.art} data-view={route.path.slice(1)}>
      <button type="button" className="oxy-public-skip" onClick={() => {
        const heading = page.current.querySelector("h1");
        if (heading) {
          heading.tabIndex = -1;
          heading.focus({ preventScroll: true });
          heading.scrollIntoView({ block: "start", behavior: "instant" });
        }
      }}>Skip to page content</button>
      <NavigationContext.Provider value={navigation}>
        <LocationContext.Provider value={{ location, navigationType }}>
          <React.Fragment key={location.pathname}>
            {renderMatches(matches)}
          </React.Fragment>
        </LocationContext.Provider>
      </NavigationContext.Provider>
    </div>
  );
}
